// utils/middleware.js
// Centralised middleware functions for the Express application.

// Express error-handling middleware requires four arguments: (error, req, res, next).
// The presence of the 'error' parameter as the first argument signals to Express that this is error-handling safety middleware.
const errorHandler = (error, req, res, next) => {
  // Log error message generated by Sequelize/PostgreSQL to the server terminal for debugging/monitoring.
  console.error(error.message)

  // if: error is Sequelize validation error
  if (error.name === 'SequelizeValidationError') {
    // Iterates through Sequelize's array of validation errors (error.errors), and extract just the text message property from each individual error object.
    const messages = error.errors.map(e => e.message)
    // Sends HTTP 400 (Bad Request) status code back to the client, along with a JSON object where the 'error' key holds the array of message strings.
    return res.status(400).json({ error: messages })
  }

  // else: Send HTTP 400 (Bad Request) code back with a JSON object containing the specific error message generated by Sequelize/PostgreSQL.
  return res.status(400).json({ error: error.message })
}
// Export the middleware function wrapped in an object so it can be imported and registered in index.js.
// Future expansion: Other middleware can be added here at some point as required.
module.exports = {
  errorHandler
}